/* ---------------------------------------------------------------------------------------------
   Type scale. Every text role uses one of these sizes so like elements match across pages.
   Kept last so it wins over the scattered per-component sizes above. */
:root{--fs-caption:12px;--fs-small:14px;--fs-body:16px;--fs-subtitle:22px;--fs-h3:20px;--fs-h2:28px;--fs-stat:26px}
body{font-size:var(--fs-body)}
/* Section headings and their subtitles */
h2{font-size:var(--fs-h2)}
.sub,.section-title span,.panel-heading p,.database-banner p:not(.eyebrow){font-size:var(--fs-subtitle);line-height:1.35}
body[data-view=stress] .intro h1,body[data-view=plan] .intro h1{font-size:32px}
/* Card headings */
.outcome h3,.chart h3,.explanation h3,.plan-card h3,.empty h3{font-size:var(--fs-h3)}
/* Body text */
.message,.message ul,#query,.comparison,.outcome p,.explanation,.plan-status,.plan-steps,.plan-numbers,
.plan-numbers>div,summary,#welcome-status{font-size:var(--fs-body)}
/* Supporting text: notes under values, help text, form labels */
.metric small,.mini small,.chart small,.plan-help,.plan-card small,.form-grid label,.clarify label,.step,
.composer-footer small,.account-box small,details.data,.fine-print,#user-count{font-size:var(--fs-small)}
/* Captions: eyebrows, field labels, table headers, badges, footer */
.eyebrow,.account-box label,.metric label,.comparison th,.header-note,.badge,.mode-switch,footer,
#database-count{font-size:var(--fs-caption)}
/* Big numbers */
.metric strong,.mini strong{font-size:var(--fs-stat)}
@media(max-width:800px){:root{--fs-subtitle:18px;--fs-h2:24px;--fs-stat:22px}}

