}

// Curved paths between the centre and each of n equal-width columns (out = splitting, in = merging).
function Fan({ n, dir }) {
  const xs = Array.from({ length: n }, (_, k) => ((k + 0.5) / n) * 100);
  return (
    <svg className="lin-fan" viewBox="0 0 100 40" preserveAspectRatio="none" aria-hidden="true">
