        <path key={x} pathLength="1" vectorEffect="non-scaling-stroke"
          d={dir === 'out' ? `M50 0 C50 22 ${x} 18 ${x} 40` : `M${x} 0 C${x} 22 50 18 50 40`} />
      ))}
