@media(max-width:800px){:root{--fs-subtitle:18px;--fs-h2:24px;--fs-stat:22px}}

/* ---------------------------------------------------------------------------------------------
   "How did we get this data?" pill next to Your starting point: a ? circle whose right side expands on hover. */
.title-with-help{display:flex;align-items:center;gap:12px;min-width:0}
.title-with-help h2{margin:0}
.help-pill{display:inline-flex;align-items:center;height:32px;padding:0;border-radius:999px;background:#fff;color:var(--orange);
  border:1.5px solid var(--orange);box-shadow:none;overflow:hidden;flex:none;transition:background .25s,box-shadow .25s}
.section-title .help-pill .help-icon{width:29px;height:29px;display:grid;place-items:center;font-size:15px;font-weight:700;flex:none}
.section-title .help-pill .help-text{max-width:0;opacity:0;white-space:nowrap;font-size:var(--fs-small);font-weight:600;
  transition:max-width .35s cubic-bezier(.2,.8,.2,1),opacity .2s,padding .35s;padding-right:0}
.help-pill:hover,.help-pill:focus-visible{background:#fff4e8;box-shadow:0 4px 12px #f5822026;filter:none}
.section-title .help-pill:hover .help-text,.section-title .help-pill:focus-visible .help-text{max-width:240px;opacity:1;padding-right:14px}

/* Data lineage screen: a tree that grows one step every 0.8s. */
.lineage-head{display:flex;align-items:flex-start;gap:20px;margin-bottom:28px}
.lineage-head>div{flex:1;min-width:0}
.lineage-head h1{margin:8px 0}
.lineage-head .sub{font-size:var(--fs-body)}
.lineage-back,.lineage-replay{flex:none;background:#fff;color:var(--ink);border:1px solid var(--line);box-shadow:none}
.lineage-replay{color:var(--orange);border-color:var(--orange)}
.lineage{list-style:none;margin:0 auto 60px;padding:0;max-width:820px}
.lineage>li{display:flex;flex-direction:column;align-items:center}
.lin-link{width:2px;height:30px;background:var(--orange);transform-origin:top;animation:lin-grow .3s ease-out both}
.lin-fan{display:block;width:100%;height:44px;overflow:visible}
.lin-fan path{fill:none;stroke:var(--orange);stroke-width:2;stroke-dasharray:1;animation:lin-draw .4s ease-out both}
.lin-columns{display:grid;width:100%}
.lin-column{display:flex;justify-content:center;padding:0 5px;min-width:0}
.lin-node{display:flex;align-items:center;gap:14px;width:min(100%,500px);padding:14px 18px;background:#fff;border:1px solid var(--line);
  border-radius:14px;box-shadow:0 8px 24px #c8640a0d,0 2px 6px #c8640a08;animation:lin-in .35s ease-out .15s both;min-width:0}
.lin-node.active{border-color:var(--orange)}
.lin-text{flex:1;min-width:0}
.lin-text strong{display:block;font-size:var(--fs-body)}
.lin-text small{display:block;color:var(--muted);font-size:var(--fs-small);line-height:1.5;margin-top:2px}
.lin-value{text-align:right;flex:none}
.lin-value small{display:block;color:var(--muted);font-size:var(--fs-caption)}
.lin-value b{font-size:20px;color:var(--orange)}
.lin-dot{width:20px;height:20px;flex:none;border-radius:50%;border:2.5px solid var(--line);position:relative;box-sizing:border-box}
.lin-node.active .lin-dot{border-top-color:var(--orange);border-right-color:var(--orange);animation:lin-spin .7s linear infinite}
.lin-node.done .lin-dot{background:var(--orange);border-color:var(--orange)}
.lin-node.done .lin-dot::after{content:"";position:absolute;left:5px;top:2px;width:5px;height:9px;border:solid #fff;border-width:0 2px 2px 0;transform:rotate(45deg)}
.lin-node.branch{flex-direction:column;text-align:center;gap:8px;padding:12px 8px;width:100%}
.lin-node.branch .lin-text strong{font-size:var(--fs-small);overflow-wrap:anywhere}
.lin-node.branch .lin-text small{font-size:var(--fs-caption)}
@keyframes lin-grow{from{transform:scaleY(0)}}
@keyframes lin-draw{from{stroke-dashoffset:1}to{stroke-dashoffset:0}}
@keyframes lin-in{from{opacity:0;transform:translateY(-8px)}}
@keyframes lin-spin{to{transform:rotate(360deg)}}
@media(max-width:640px){.lineage-head{flex-wrap:wrap}.lineage-head>div{order:3;flex-basis:100%}
.lin-node{flex-wrap:wrap}.lin-value{text-align:left}.lin-node.branch .lin-text small{display:none}}

